// FatFs often expects "0:/path". This helper prepends "0:" if missing.
// Returned pointer is either original path (no allocation) or malloc'ed.
static const char* _ff_path(const char *path, char **allocated)
{
    *allocated = NULL;
    if (!path) return NULL;

    // Already has drive like "0:" or "1:"
    if (strlen(path) >= 2 && path[1] == ':') {
        return path;
    }

    // Make "0:" + path
    size_t n = strlen(path);
    char *p = (char*)malloc(n + 3);
    if (!p) return NULL;

    p[0] = '0';
    p[1] = ':';
    // allow either "/foo" or "foo"
    if (path[0] == '/') {
        memcpy(&p[2], path, n + 1);
    } else {
        p[2] = '/';
        memcpy(&p[3], path, n + 1);
    }

    *allocated = p;
    return p;
}

// Parse "r", "w", "a", "r+", "w+", "a+" into FatFs flags.
static BYTE _mode_to_fa(const char *mode)
{
    if (!mode || !mode[0]) return FA_READ;

    int plus = (strchr(mode, '+') != NULL);
    char m = mode[0];

    if (m == 'r') {
        return plus ? (FA_READ | FA_WRITE | FA_OPEN_EXISTING) : (FA_READ | FA_OPEN_EXISTING);
    } else if (m == 'w') {
        return plus ? (FA_READ | FA_WRITE | FA_CREATE_ALWAYS) : (FA_WRITE | FA_CREATE_ALWAYS);
    } else if (m == 'a') {
        // FatFs append: open always + seek end
        return plus ? (FA_READ | FA_WRITE | FA_OPEN_APPEND) : (FA_WRITE | FA_OPEN_APPEND);
    }

    return FA_READ;
}
